  ["Needs %s."] = "Necesita %s.",
  ["One key clears the screen for the view"] = "Una tecla despeja la pantalla para la vista",
  ["One key hides the interface but the action bars."] = "Una tecla oculta la interfaz salvo las barras de acción.", -- luacheck: ignore 631
  ["Or switch everything on"] = "O activarlo todo",
  ["Pins on the minimap"] = "Marcadores en el minimapa",
  ["Prices, and who of your characters has what"] = "Precios, y cuál de tus personajes tiene qué",
  ["Quest givers' words around the Orbiter, your answers as symbols."] = "Las palabras de quienes dan misiones alrededor del Orbiter, tus respuestas como símbolos.", -- luacheck: ignore 631
  ["Rings of your emotes, lines and macros on one key; a thank-you when someone buffs or resurrects you; a bow or a polite no to a duel or a trade."] = "Anillos de tus emociones, frases y macros en una tecla; un gracias cuando alguien te mejora o te resucita; una reverencia o un no cortés a un duelo o un comercio.", -- luacheck: ignore 631
  ["Roleplay with Bastian's"] = "Rol con Bastian's",
  ["Route steps"] = "Pasos de la ruta",
  ["Route there on anything: road, flight, boat."] = "Una ruta hacia cualquier cosa: camino, vuelo, barco.",
  ["Show the welcome at every login"] = "Mostrar la bienvenida en cada inicio de sesión",
  ["Sit by a fire together, share it with your group, a camp ring for the evening."] = "Sentarse juntos junto a una hoguera, compartirla con tu grupo, un anillo de campamento para la noche.", -- luacheck: ignore 631
  ["Switch on %s on the Suite page."] = "Activa %s en la página Suite.",
  ["Talk to a quest giver with the conversation on"] = "Hablar con quien da una misión con la conversación activada", -- luacheck: ignore 631
  ["Talk to people without quest windows"] = "Hablar con la gente sin ventanas de misión",
  ["Text"] = "Texto",
  ["The Gestures ring"] = "El anillo de Gestos",
  ["The Orbiter"] = "El Orbiter",
  ["The Orbiter plays Spoken's voices for quests, places, books and bosses, and the game's voice where Spoken has none."] = "El Orbiter reproduce las voces de Spoken para misiones, lugares, libros y jefes, y la voz del juego donde Spoken no tiene.", -- luacheck: ignore 631
  ["The Orbiter plays the zone's story."] = "El Orbiter reproduce la historia de la zona.",
  ["The campfire"] = "La hoguera",
  ["The hub: every app's settings, the Suite page, Help."] = "El centro: los ajustes de cada aplicación, la página Suite, la ayuda.", -- luacheck: ignore 631
  ["The land speaks"] = "La tierra habla",
  ["The land tells its stories as you walk (the Orbiter with Spoken)"] = "La tierra cuenta sus historias mientras caminas (el Orbiter con Spoken)", -- luacheck: ignore 631
  ["The screen for the view"] = "La pantalla para la vista",
  ["The search opens a page for anything."] = "La búsqueda abre una página para cualquier cosa.",
  ["The suite's button at the minimap"] = "El botón de la suite en el minimapa",
  ["The suite's words"] = "Las palabras de la suite",
  ["The way there, by road, flight and boat"] = "El camino, por carretera, vuelo y barco",
  ["The welcome stays away at login; the General page brings it back."] = "La bienvenida ya no aparece al iniciar sesión; la página General la recupera.", -- luacheck: ignore 631
  ["The welcome window at every login, until Don't show again in its corner (plan-launch-version D)."] = "La ventana de bienvenida en cada inicio de sesión, hasta No volver a mostrar en su esquina (plan-launch-version D).", -- luacheck: ignore 631
  ["Try it"] = "Probar",
  ["What matters for this way"] = "Lo que importa en este camino",
  ["What you get"] = "Lo que obtienes",
  ["Where things are"] = "Dónde están las cosas",
  ["You know the way."] = "Ya conoces el camino.",
  ["Your first five minutes"] = "Tus primeros cinco minutos",
  ["Your gestures on a ring, thanks in your own words"] = "Tus gestos en un anillo, gracias con tus propias palabras", -- luacheck: ignore 631
  ["Your pack"] = "Tu equipaje",
  -- the welcome's information layer (02.11.2026)
  ["Highpeak"] = "Pico Alto",
  ["Greenback Ridge"] = "Cresta Lomoverde",
  ["Peacebloom"] = "Flor de paz",
  ["%d yd high, %d yd away"] = "%d m de alto, a %d m",
  ["%d yd away"] = "a %d m",
  -- the artist's credit under a hand-drawn dungeon map (ADR 0048, 02.11.2026)
  ["Map by %s"] = "Mapa de %s",
  ["Map by %s (%s), used with kind permission. Thank you!"] = "Mapa de %s (%s), usado con su amable permiso. ¡Gracias!",
  ["Click, then Ctrl+C to copy the address"] = "Haz clic y luego Ctrl+C para copiar la dirección",
  -- the minimap buttons
  ["Welcome"] = "Bienvenida",
  ["Its own minimap button for the welcome"] = "Su propio botón en el minimapa para la bienvenida",
  ["A button at the minimap that shows the welcome with the Wanderer and the Scholar again."] = "Un botón en el minimapa que vuelve a mostrar la bienvenida con el Errante y el Erudito.",
  ["%s is switched off. Its page has the switch to turn it on."] = "%s está desactivado. Su página tiene el interruptor para activarlo.",
  ["Click: its page, to switch it on."] = "Clic: su página, para activarlo.",

  -- What's new (ADR 0021, LG5): the release notes, keyed by their English text
  ["The map styles and the overview pictures are back in the Suite's download. Releases 2.2.0 and 2.3.0 had moved them to a separate download that cannot be installed yet, so the map lost its pictures on an update."] = "Los estilos de mapa y las imágenes generales vuelven a estar en la descarga de la suite. Las versiones 2.2.0 y 2.3.0 los habían movido a una descarga aparte que todavía no se puede instalar, así que el mapa perdía sus imágenes al actualizar.",
  ["Courtesy's thank-yous now know what you were given, where you are, the weather and whether you were fighting, with 957 lines instead of 209."] = "Los agradecimientos de Cortesía saben ahora qué te dieron, dónde estás, qué tiempo hace y si estabas luchando, con 957 frases en lugar de 209.",
  ['Stormwind has a painted City & dungeon map in its own window: the "City map" button on the map opens it, with your position, the map\'s layers and a pin for every house and the people in it. Release 2.2.0 had left its pictures out.'] = 'Ventormenta tiene un Mapa de ciudades y mazmorras pintado en su propia ventana: el botón "Mapa de ciudad" del mapa lo abre, con tu posición, las capas del mapa y un marcador para cada casa y la gente que hay en ella. La versión 2.2.0 había dejado fuera sus imágenes.',
  ['Quests show the zone where you pick them up, and "from" on a collect objective only names a creature that really has the item.'] = 'Las misiones muestran la zona donde las recoges, y "de" en un objetivo de recolección solo nombra a una criatura que realmente tiene el objeto.',
  ["Quest givers and hand-ins that ForeverDB players saw in the game fill gaps on the map sooner."] = "Los que dan misiones y los lugares de entrega que los jugadores de ForeverDB vieron en el juego llenan antes los huecos del mapa.",
  ["A rumour in the gold book names its three newest travellers and counts the others."] = "Un rumor del libro del oro nombra a sus tres viajeros más recientes y cuenta a los demás.",
  ["A quest whose next step has no known place no longer routes you back to its giver."] = "Una misión cuyo siguiente paso no tiene un lugar conocido ya no te lleva de vuelta a quien la da.",
  ['A quest whose place nobody knows says so, with Map and Route greyed; the quest round stops once per open objective, and "Route to" picks among the nearest places.'] = 'Una misión cuyo lugar nadie conoce lo dice, con Mapa y Ruta en gris; la ronda de misiones se detiene una vez por objetivo abierto, y "Ruta a" elige entre los lugares más cercanos.',
  ["Quests that ask for an item no loot table knew, like Mirror Lake's water sample, now lead to where the item is found."] = "Las misiones que piden un objeto que ninguna tabla de botín conocía, como la muestra de agua del Lago Espejo, ahora llevan a donde se encuentra el objeto.",
  ['The suite notes where your quest steps counted, and "Copy my captures" can share those places, so quests no source can place get one later.'] = 'La suite anota dónde contaron los pasos de tus misiones, y "Copiar mis capturas" puede compartir esos lugares, para que las misiones que ninguna fuente sabe situar reciban uno más adelante.',
  ["The flight bar and the learned flight times name the flight you took; the game lists its flight points in another order than its buttons."] = "La barra de vuelo y los tiempos de vuelo aprendidos nombran el vuelo que tomaste; el juego lista sus puntos de vuelo en un orden distinto al de sus botones.",
  ["Abandoning a quest that takes items back no longer raises an error; the game's question names the items."] = "Abandonar una misión que retira objetos ya no provoca un error; la pregunta del juego nombra los objetos.",
  ["A reload or a logout at the mailbox no longer raises an error in Alts."] = "Una recarga o una desconexión en el buzón ya no provoca un error en Personajes.",
  ["Ring wedges and the Campfire's foot icon act on a click whatever the game's key-down setting, and a ring opened by its toggle key stays until that key closes it, over a reload too."] = "Los segmentos de los anillos y el icono del pie de la Hoguera responden a un clic sea cual sea el ajuste de pulsación de teclas del juego, y un anillo abierto con su tecla de alternar se queda hasta que esa tecla lo cierra, también tras una recarga.",
  ["Courtesy whispers its line to the person who buffed or invited you when the game gives their whole name, and offers its ring for a buff that landed during a longer fight."] = "Cortesía susurra su frase a la persona que te dio un beneficio o te invitó cuando el juego da su nombre completo, y ofrece su anillo para un beneficio que llegó durante un combate más largo.",
  ["Gold's ledger now books your auction house sales and purchases when you open the mailbox; it raised an error instead."] = "El libro de Gold anota ahora tus ventas y compras en la casa de subastas cuando abres el buzón; en su lugar provocaba un error.",
  ["The flight bar goes away when you land, and Route now learns how long your flights take; on WoW Forever it never noticed a landing."] = "La barra de vuelo desaparece cuando aterrizas, y Route aprende ahora cuánto duran tus vuelos; en WoW Forever nunca notaba un aterrizaje.",
  ["The map no longer sends you to quest givers who are not there or have nothing to give: world event quests wait for their event, quests that are not in the game are gone, and a giver who does not list a quest loses its pin until you gain a level."] = "El mapa ya no te envía a dadores de misiones que no están o que no tienen nada que dar: las misiones de eventos del mundo esperan a su evento, las misiones que no existen en el juego desaparecen, y un dador que no lista una misión pierde su marca hasta que subas de nivel.",
  ['Quests far below your level stay on the map in grey, marked "Low level".'] = 'Las misiones muy por debajo de tu nivel se quedan en el mapa en gris, marcadas con "Nivel bajo".',
  ["The gold stories' map scales smoothly with its window, which takes the map's shape; tokens light up under the cursor; the book opens on the map."] = "El mapa de las historias de oro se escala con suavidad con su ventana, que adopta la forma del mapa; las fichas se iluminan bajo el cursor; el libro se abre en el mapa.",
  ["Zone level ranges on the map are coloured for your character's level."] = "Los rangos de nivel de las zonas en el mapa se colorean según el nivel de tu personaje.",
  ['A dungeon in a list says "in 4 levels" while it is still ahead of you.'] = 'Una mazmorra en una lista dice "en 4 niveles" mientras aún te queda por delante.',
  ["A zone's page says the fishing skill it asks for."] = "La página de una zona indica la habilidad de pesca que exige.",
  ["The map's footer shows the travel time to the point under your cursor."] = "El pie del mapa muestra el tiempo de viaje hasta el punto bajo tu cursor.",
  ["Items whose cheapest listing is far under their 30-day median are marked as a bargain."] = "Los objetos cuyo anuncio más barato está muy por debajo de su mediana de 30 días se marcan como una ganga.",
  ["A small bar shows the time left on a flight whose duration you flew before."] = "Una barra pequeña muestra el tiempo restante de un vuelo que ya has hecho antes.",
  ["Dungeon pages list the quests whose targets live inside, from the Classic data, for 16 more dungeons and raids."] = "Las páginas de mazmorra listan las misiones cuyos objetivos viven dentro, según los datos de Classic, para 16 mazmorras y bandas más.",
  ['A "Class quests" view lists your class\'s quests by status and level.'] = 'Una vista "Misiones de clase" lista las misiones de tu clase por estado y nivel.',
  ["Targeting or mousing over a rare creature shows its name with a Map button."] = "Al fijar como objetivo una criatura rara o pasar el ratón por encima se muestra su nombre con un botón Mapa.",
  ["A route says in one word whether the way is safe, needs care or is risky for your level."] = "Una ruta dice en una palabra si el camino es seguro, exige cuidado o es arriesgado para tu nivel.",
  ['"Craft for gold" lists the recipes you know by profit, with the best way to sell each product.'] = '"Fabricar por oro" lista las recetas que conoces por beneficio, con la mejor forma de vender cada producto.',
  ['A "Trainer" view lists the spells your class trainers teach you now, with cost and the nearest trainer.'] = 'Una vista "Instructor" lista los hechizos que tus instructores de clase te enseñan ahora, con el coste y el instructor más cercano.',
  ["Your character's page names the gold to save for: the next training, riding and a mount."] = "La página de tu personaje indica el oro que debes ahorrar: el próximo entrenamiento, la equitación y una montura.",
  ["A dungeon's page lists your characters' runs and lockouts."] = "La página de una mazmorra lista las pasadas y los bloqueos de tus personajes.",
  ["A farm spot's page shows your own gold per hour there after twenty kills, beside the guide's figure."] = "La página de un lugar de farmeo muestra, tras veinte muertes, tu propio oro por hora allí, junto a la cifra de la guía.",
  ["The Atlas has a rail of seven sections with tabs instead of a bar of nineteen buttons."] = "El Atlas tiene un carril de siete secciones con pestañas en lugar de una barra de diecinueve botones.",
  ["The Atlas's search stands in the title bar, always at hand."] = "La búsqueda del Atlas está en la barra de título, siempre a mano.",
  ["The Atlas's lists come in pages that fit the window instead of a scroll."] = "Las listas del Atlas se muestran en páginas que caben en la ventana en lugar de un desplazamiento.",
  ["Stat tiles on Here, Gold and Characters; a dungeon's and a character's page read in tabs."] = "Mosaicos de estadísticas en Aquí, Gold y Personajes; la página de una mazmorra y la de un personaje se leen en pestañas.",
  ["Gold's Bags tab gives one answer per bag item with the reason."] = "La pestaña Bolsas de Gold da una respuesta por objeto de la bolsa con el motivo.",
  ["The settings hub reads as a rail of apps with their one-line purpose and every option on a card."] = "El centro de ajustes se presenta como un carril de apps con su propósito en una línea y cada opción en una tarjeta.",
  ['Share the walks, flight times and ride waits your game learned through "Copy my captures" in the settings.'] = 'Comparte los recorridos a pie, los tiempos de vuelo y las esperas de viaje que tu juego ha aprendido mediante "Copiar mis capturas" en los ajustes.',
  ["Dragging a window no longer jumps it over the top of the screen, and Dock works again after the docked Browser was closed by hand."] = "Arrastrar una ventana ya no la lanza por encima del borde superior de la pantalla, y Acoplar vuelve a funcionar después de cerrar a mano el Navegador acoplado.",
  ["In a narrow Browser window a click on a view's row now shows the page it opens."] = "En una ventana estrecha del Navegador, un clic en la fila de una vista ahora muestra la página que abre.",
  ["The Browser's search always looks in every list; the list's own filter narrows the list."] = "La búsqueda del Navegador siempre mira en todas las listas; el filtro propio de la lista acota la lista.",
  ["The physical map no longer shows a stray strip of old parchment west of Kalimdor."] = "El mapa físico ya no muestra una franja suelta de pergamino viejo al oeste de Kalimdor.",
  ["The level band under a zone's name on the map reads clearly in every difficulty colour."] = "El rango de nivel bajo el nombre de una zona en el mapa se lee con claridad en cada color de dificultad.",
  ["A farm spot without a known gold rate says so once, and the text is no longer cut off."] = "Un lugar de farmeo sin tasa de oro conocida lo dice una sola vez, y el texto ya no se corta.",
  ["A quest's sheet under the mouse on a chain's step shows over the Browser instead of behind it."] = "La hoja de una misión bajo el ratón en un paso de una cadena se muestra sobre el Navegador en lugar de detrás.",
  ["The people on a quest's sheet show their faces again."] = "Las personas de la hoja de una misión vuelven a mostrar sus caras.",
  ['The map\'s right-click menu no longer lists "Show on map" twice.'] = 'El menú de clic derecho del mapa ya no lista "Mostrar en el mapa" dos veces.',
  ["A click on a class quest no longer empties the Class quests list while it is rebuilt."] = "Un clic en una misión de clase ya no vacía la lista Misiones de clase mientras se reconstruye.",
  ['A dungeon one level away now says "in 1 level".'] = 'Una mazmorra a un nivel de distancia ahora dice "en 1 nivel".',
  ["The gold book's text follows the suite's text size and uses three font sizes instead of seven."] = "El texto del libro del oro sigue el tamaño de texto de la suite y usa tres tamaños de letra en lugar de siete.",
  ["The gold book's maps and the story map's marks open their place on the world map."] = "Los mapas del libro del oro y las marcas del mapa de la historia abren su lugar en el mapa del mundo.",
  ["The names in the gold book's pages are links: hover for the tooltip, click to open."] = "Los nombres de las páginas del libro del oro son enlaces: pasa el ratón para ver la descripción emergente, haz clic para abrir.",
  ["A page in the Browser has its own filter: type to narrow every list on it."] = "Una página del Navegador tiene su propio filtro: escribe para acotar cada lista que contiene.",
  ["The Browser's sections and tabs are coloured symbols with text instead of green buttons."] = "Las secciones y pestañas del Navegador son símbolos de colores con texto en lugar de botones verdes.",
  ["/balts opens your characters in the Browser: the list on the left, a character's tabs on the right."] = "/balts abre tus personajes en el Navegador: la lista a la izquierda, las pestañas de un personaje a la derecha.",
  ["Gold's new Bargains tab lists the items selling far under their usual price."] = "La nueva pestaña Gangas de Gold lista los objetos que se venden muy por debajo de su precio habitual.",
  ["The Gold Stories list shows each story as a tile with Bastian's picture and its first words."] = "La lista de Historias de oro muestra cada historia como un mosaico con la imagen de Bastian y sus primeras palabras.",
  ["The map keeps you centred by default; looking around pauses it until the map closes, and only the Centred button switches it off."] = "El mapa te mantiene centrado de forma predeterminada; mirar alrededor lo pausa hasta que se cierra el mapa, y solo el botón Centrado lo desactiva.",
  ["The minimap shows only the herbs and ore the game's tracking really finds, not every known spawn."] = "El minimapa solo muestra las hierbas y minerales que el rastreo del juego realmente encuentra, no todos los puntos de aparición conocidos.",
  ["A window you open always comes to the front, also one that was already open behind another."] = "Una ventana que abres siempre pasa al frente, también una que ya estaba abierta detrás de otra.",
  ["The campfire flame can be dragged anywhere and remembers its place."] = "La llama de la hoguera se puede arrastrar a cualquier parte y recuerda su sitio.",
  ["Hovering a quest reward in the Orbiter shows the item's full stats."] = "Al pasar el ratón por una recompensa de misión en el Orbiter se muestran todas las estadísticas del objeto.",
  ["My quests lists every objective of a quest with its count, not just the first open one."] = "Mis misiones lista cada objetivo de una misión con su recuento, no solo el primero abierto.",
  ["A route starts on your side of a ridge instead of across a mountain."] = "Una ruta empieza en tu lado de una cresta en lugar de atravesar una montaña.",
  ["After you die, Bastian's Route drops the old arrow and guides you on foot back to your corpse, marked clearly on the map."] = "Tras morir, Bastian's Route descarta la flecha antigua y te guía a pie de vuelta a tu cadáver, marcado con claridad en el mapa.",
  ["/way now works without TomTom and starts a route; several lines become one route, and a button chooses a new route or adding to the current one."] = "/way ahora funciona sin TomTom e inicia una ruta; varias líneas forman una sola ruta, y un botón permite elegir entre una ruta nueva y añadir a la actual.",
  ["The map shows only the quest targets you still need, each labelled with what to do there and how many are left."] = "El mapa solo muestra los objetivos de misión que aún necesitas, cada uno con una etiqueta de lo que hay que hacer allí y cuántos quedan.",
  ["The minimap follows your character even when the game reports no movement, on boats, after a knockback or a teleport."] = "El minimapa sigue a tu personaje incluso cuando el juego no informa de movimiento: en barcos, tras un empujón o un teletransporte.",
  ["Switching a layer off also clears its pins from the minimap."] = "Desactivar una capa también quita sus marcas del minimapa.",
  ["Creatures found by hunter, druid, paladin and warlock tracking now show on Bastian's map styles."] = "Las criaturas encontradas por el rastreo de cazador, druida, paladín y brujo ahora aparecen en los estilos de mapa de Bastian's.",
  ["Bastian's Courtesy is now an addon of its own: when someone helps you, a small ring offers a fitting thank-you, and your click says it in character."] = "Bastian's Courtesy es ahora un addon propio: cuando alguien te ayuda, un pequeño anillo ofrece un agradecimiento adecuado, y tu clic lo dice en personaje.",
  ["The gesture ring stays open until you press its key again."] = "El anillo de gestos permanece abierto hasta que vuelvas a pulsar su tecla.",
  ["Routes inside Stormwind no longer detour around the harbour to reach a street nearby."] = "Las rutas dentro de Stormwind ya no dan un rodeo por el puerto para llegar a una calle cercana.",
  ["Trainers and vendors say what kind they are, also when their title has no word Trainer in it."] = "Los instructores y vendedores indican de qué tipo son, también cuando su título no contiene la palabra Instructor.",
  ["The campfire card is now a stylized flame you click: sit down, share or hide."] = "La tarjeta de la hoguera es ahora una llama estilizada en la que haces clic: sentarte, compartir u ocultar.",
  ["A new minimap button lights a kit you carry, and the foot icon offers what you can add to a fire, Violet Dust included."] = "Un nuevo botón del minimapa enciende un kit que llevas contigo, y el icono del pie ofrece lo que puedes añadir a una hoguera, Violet Dust incluido.",
  ["Send to writes a character's name with its surname, so the mail reaches them on Forever."] = "Enviar a escribe el nombre de un personaje con su apellido, para que el correo le llegue en Forever.",
  ["Alts can forget a character you deleted, and its filter now finds class, race, place and every item held."] = "Alts puede olvidar un personaje que hayas eliminado, y su filtro ahora encuentra clase, raza, lugar y cada objeto que se posee.",
  ["A new key in Key Bindings opens whatever is under your mouse in the Browser."] = "Una nueva tecla en las asignaciones de teclas abre en el Navegador lo que haya bajo tu ratón.",
  ["The quest window has a Route to the giver button."] = "La ventana de misión tiene un botón Ruta al dador.",
  ["A quest item you already hold no longer keeps its pin where it lay."] = "Un objeto de misión que ya tienes ya no conserva su marca donde estaba.",
  ["The chat's copy window has a scroll bar."] = "La ventana de copia del chat tiene una barra de desplazamiento.",
  ["The chat input bar no longer disappears behind the window, and a reload no longer takes the keyboard."] = "La barra de entrada del chat ya no desaparece detrás de la ventana, y una recarga ya no te quita el teclado.",
  ["Quests now wait for the quest players were seen to need first, where that cannot lock them out."] = "Las misiones ahora esperan a la misión que se vio que los jugadores necesitaban primero, donde eso no pueda bloquearlas.",
  ['The Browser\'s search no longer stays on "Searching ..." while other things happen; a search that fails says so.'] = 'La búsqueda del Browser ya no se queda en "Buscando ..." mientras ocurren otras cosas; una búsqueda que falla lo dice.',
  ["Bastian's Route now has the walk network of both continents: routes follow roads, passes and bridges instead of the straight line."] = "Bastian's Route tiene ahora la red de caminos de ambos continentes: las rutas siguen carreteras, pasos y puentes en vez de la línea recta.",
  ["The herbs and ore the game tracks no longer vanish from Bastian's minimap styles with a map layer, the pin limit or the layers-on-the-minimap setting; they show as yellow pins of their own."] = "Las hierbas y minerales que rastrea el juego ya no desaparecen de los estilos del minimapa de Bastian por una capa del mapa, el límite de marcas o el ajuste de capas en el minimapa; se muestran como marcas amarillas propias.",
  ["Gold finds the market prices on the live EU RP realm."] = "Gold encuentra los precios del mercado en el reino RP de la UE en directo.",
  ["Herbs and ore on Bastian's minimap styles now sit exactly where the game's own dots are."] = "Las hierbas y minerales en los estilos del minimapa de Bastian ahora están exactamente donde están los puntos del propio juego.",
  ["Hovering a quest lights its whole block in one colour and the row under the mouse in another, so chain quests no longer look like quests of their own."] = "Al pasar el ratón por una misión, todo su bloque se ilumina de un color y la fila bajo el ratón de otro, así que las cadenas de misiones ya no parecen misiones sueltas.",
  ["Quests now say what to do first: the task sits right under the quest in My quests and opens the quest page, with the story last."] = "Las misiones ahora dicen primero qué hacer: la tarea está justo debajo de la misión en Mis misiones y abre la página de la misión, con la historia al final.",
  ['Objectives show their count once, a quest with one objective counts its items, and "worth unknown" no longer fills a line.'] = "Los objetivos muestran su cantidad una sola vez, una misión con un solo objetivo cuenta sus objetos, y 'valor desconocido' ya no ocupa una línea.",
  ["Bastian's minimap styles show only the herbs and ore your tracking finds, no more stray pins on you or on quest marks."] = "Los estilos del minimapa de Bastian solo muestran las hierbas y minerales que encuentra tu rastreo, sin más marcas sueltas sobre ti o sobre las marcas de misión.",
  ["Quests now open on a parchment sheet with the task first, the story and large rewards, from My quests, the map and on hover at the Orbiter's quest marks."] = "Las misiones ahora se abren en una hoja de pergamino con la tarea primero, la historia y recompensas grandes: desde Mis misiones, desde el mapa y al pasar el ratón por las marcas de misión del Orbiter.",
  ["Rewards come from the game itself, so quests no source knows show their real experience, money and items."] = "Las recompensas vienen del propio juego, así que las misiones que ninguna fuente conoce muestran su experiencia, dinero y objetos reales.",
  ["My quests shows each quest on two lines, a finished quest has its own mark and says who takes it, and the voice and chain buttons stay on the row."] = "Mis misiones muestra cada misión en dos líneas, una misión terminada tiene su propia marca y dice quién la recoge, y los botones de voz y de cadena se quedan en la fila.",
  ["The chain symbol shows a quest chain as a trail with every step, what it needs and what is still ahead."] = "El símbolo de cadena muestra una cadena de misiones como un sendero con cada paso, lo que requiere y lo que queda por delante.",
  ["The map shows the targets of one quest, the focused or the nearest, and finished quests' hand-ins as large signs."] = "El mapa muestra los objetivos de una sola misión, la enfocada o la más cercana, y los lugares de entrega de las misiones terminadas como signos grandes.",
  ["A second click on a quest closes its sheet, and the sheet shows the quest giver and the target in 3D."] = "Un segundo clic en una misión cierra su hoja, y la hoja muestra al dador de la misión y el objetivo en 3D.",
  ["Show on map opens at the nearest group of a quest's targets, not between two far camps."] = "Mostrar en el mapa se abre en el grupo de objetivos más cercano de una misión, no entre dos campamentos lejanos.",
  ["Auctioneers, stable masters, innkeepers, bankers, flight masters and battlemasters are marked as what they are, and several hundred more vendors and repairers are found."] = "Los subastadores, maestros de establos, taberneros, banqueros, maestros de vuelo y maestros de batalla se marcan como lo que son, y se encuentran varios cientos más de vendedores y reparadores.",
  ["A page in the Browser reads like the quest sheet: the figure large at the left on a wide window, the name and what matters first, the main buttons with the rest under More, and chapters in one column instead of a grid of blocks."] = "Una página del Navegador se lee como la hoja de misión: la imagen grande a la izquierda en una ventana ancha, el nombre y lo importante primero, los botones principales con el resto en Más, y los capítulos en una columna en lugar de una cuadrícula de bloques.",
  ['Pages are sorted into chapters in a fixed reading order: a zone\'s quests under one heading, an item under "Where to get it", "What it is for", "Worth" and "Yours", a monster\'s drops first.'] = "Las páginas se ordenan en capítulos con un orden de lectura fijo: las misiones de una zona bajo un solo título, un objeto bajo 'Dónde conseguirlo', 'Para qué sirve', 'Valor' y 'Tuyo', y de un monstruo, primero sus botines.",
  ["A page in the Browser is drawn on parchment like the quest sheet, its rows are calm (two lines, icons only under the mouse), and a zone's quest groups you cannot act on yet are folded until clicked."] = "Una página del Navegador se dibuja en pergamino como la hoja de misión, sus filas son tranquilas (dos líneas, iconos solo bajo el ratón), y los grupos de misiones de una zona en los que aún no puedes actuar están plegados hasta que hagas clic.",
  ["A zone's page lists its people by what they do, vendors, trainers, zones and dungeons say in one sentence what they are, quests far above your level no longer lead \"To do here\", and pages on parchment keep the paper's colours under the mouse and switch without a reload."] = "La página de una zona lista a sus habitantes según lo que hacen, los vendedores, instructores, zonas y mazmorras dicen en una frase qué son, las misiones muy por encima de tu nivel ya no encabezan 'Por hacer aquí', y las páginas en pergamino conservan los colores del papel bajo el ratón y cambian sin recargar.",
  ["Stormwind's bankers, guards, mailboxes and other people and objects inside the city are listed and shown in Stormwind City, no longer in Elwynn Forest."] = "Los banqueros, guardias, buzones y otros personajes y objetos de Stormwind dentro de la ciudad se enumeran y se muestran en Stormwind City, ya no en Elwynn Forest.",
  ["Test and placeholder records of the game's data (unused NPCs, invisible triggers, deprecated and test items, the weapons monsters hold) no longer show in lists, zone pages and the search."] = "Los registros de prueba y de relleno de los datos del juego (PNJ sin uso, activadores invisibles, objetos obsoletos y de prueba, las armas que sostienen los monstruos) ya no aparecen en las listas, las páginas de zona ni la búsqueda.",
  ['"To do here" ranks a quest by the experience it really gives where the game data names it, no longer by an estimate from its level.'] = "'Por hacer aquí' ordena una misión por la experiencia que realmente da cuando los datos del juego la indican, ya no por una estimación a partir de su nivel.",
  ["Pages on parchment keep readable colours everywhere, a place's mini map opens the large map there, a dungeon's floor map no longer sticks to other pages, the quest sheet opens on the free side of the Orbiter, and a locked Orbiter says that it is locked."] = "Las páginas en pergamino conservan colores legibles en todas partes, el minimapa de un lugar abre allí el mapa grande, el mapa de planta de una mazmorra ya no se queda pegado a otras páginas, la hoja de misión se abre en el lado libre del Orbiter, y un Orbiter fijado dice que está fijado.",
  ["The Browser's navigation is a bar of category buttons on top, and the list always stands beside the page as two tiles; a narrow or docked window shows one of them at a time."] = "La navegación del Navegador es una barra de botones de categoría arriba, y la lista siempre está junto a la página como dos mosaicos; una ventana estrecha o acoplada muestra uno a la vez.",
  ["The Browser's lists and search results are tiles: a picture, the name and a line that says what it is."] = "Las listas y los resultados de búsqueda del Navegador son mosaicos: una imagen, el nombre y una línea que dice qué es.",
  ["Browser lists show each thing as a tile with its own facts: a quest's state, giver, level and chain step, a monster's level and rank, a zone's level band."] = "Las listas del Navegador muestran cada cosa como un mosaico con sus propios datos: de una misión, su estado, dador, nivel y paso de cadena; de un monstruo, su nivel y rango; de una zona, su rango de niveles.",
  ["The Orbiter has a small lock under its play button: click it to lock the ring in place or to move it freely."] = "El Orbiter tiene un pequeño candado bajo su botón de reproducir: haz clic para fijar el anillo en su sitio o moverlo libremente.",
  ["The Browser's Slim mode is gone; the quest tracker frame (/bq tracker) is the tracker, and a Browser left in slim mode opens wide again."] = "El modo Slim del Navegador ha desaparecido; el marco de seguimiento de misiones (/bq tracker) es el seguimiento, y un Navegador que se quedó en modo Slim se abre de nuevo ancho.",
  ["The Browser's filters stand beside the search box, and a chip inside the box says where the list and the search look: your zone, your continent or everywhere."] = "Los filtros del Navegador están junto al cuadro de búsqueda, y una etiqueta dentro del cuadro indica dónde buscan la lista y la búsqueda: tu zona, tu continente o en todas partes.",
  ["A page in the Browser shows its parts as cards: a zone's quests, people and monsters as tiles, four at a glance and the rest one click away, with nothing folded."] = "Una página del Navegador muestra sus partes como tarjetas: las misiones, habitantes y monstruos de una zona como mosaicos, cuatro de un vistazo y el resto a un clic, sin nada plegado.",
  ["A quest's page in the Browser is the same quest sheet as beside the Orbiter: the task first, the story, the rewards as tiles, with its people and its chain as cards below."] = "La página de una misión en el Navegador es la misma hoja de misión que junto al Orbiter: primero la tarea, la historia, las recompensas como mosaicos, con sus habitantes y su cadena como tarjetas debajo.",
  ["A zone, a person or a dungeon in the Browser can be stepped into: a click on the edge of its tile shows its quests, people and monsters in the list, one group open at a time, while the page shows what you pick."] = "En el Navegador se puede entrar en una zona, un personaje o una mazmorra: un clic en el borde de su mosaico muestra sus misiones, habitantes y monstruos en la lista, con un grupo abierto a la vez, mientras la página muestra lo que eliges.",
  ["A quest chain is a page of its own: the Quest chains list opens the chain with its steps in order, how far you are, the next step and the zones it leads through."] = "Una cadena de misiones es una página propia: la lista Cadenas de misiones abre la cadena con sus pasos en orden, hasta dónde has llegado, el siguiente paso y las zonas por las que pasa.",
  ["A quest chain's page shows its way as coloured step tiles joined by arrows; the mouse on a step shows that quest's sheet and a click opens it."] = "La página de una cadena de misiones muestra su camino como mosaicos de pasos de colores unidos por flechas; el ratón sobre un paso muestra la hoja de esa misión y un clic la abre.",
  ["A quest in a chain shows its step, the chain and the steps before and after under its name; the chain button opens the chain's page instead of a window of its own."] = "Una misión de una cadena muestra bajo su nombre su paso, la cadena y los pasos anteriores y posteriores; el botón de cadena abre la página de la cadena en lugar de una ventana propia.",
  ["A zone's page lists the quest chains that pass through it, and the chain list is grouped by how far you are, with filters for progress, kind and length."] = "La página de una zona enumera las cadenas de misiones que pasan por ella, y la lista de cadenas se agrupa según hasta dónde has llegado, con filtros de progreso, tipo y longitud.",
  ["A chain's page shows its side quests under the step they follow, and the steps of other races and classes dashed."] = "La página de una cadena muestra sus misiones secundarias bajo el paso al que siguen, y los pasos de otras razas y clases con líneas discontinuas.",
  ["Follow on a quest chain's page tracks the step you are on and, after the hand-in, the next one by itself."] = "Seguir en la página de una cadena de misiones sigue el paso en el que estás y, tras la entrega, el siguiente por sí solo.",
  ["The Browser's lists are named People, Monsters, Gathering and Chains, and a list with nothing in it shows no button."] = "Las listas del Navegador se llaman Habitantes, Monstruos, Recolección y Cadenas, y una lista vacía no muestra ningún botón.",
  ["The coloured words on parchment pages and on the quest sheet are darker, so they read against the paper; a few colours on list tiles are a touch brighter."] = "Las palabras de color en las páginas de pergamino y en la hoja de misión son más oscuras, para que se lean sobre el papel; algunos colores de los mosaicos de las listas son un poco más claros.",
  ["A double click on a tile in the Browser's list steps inside the thing, like the arrow at the tile's edge."] = "Un doble clic en un mosaico de la lista del Navegador entra en la cosa, como la flecha en el borde del mosaico.",
  ["A thing's places show as a small map of each zone in your map style, with a dot for every place; a click opens the large map there."] = "Los lugares de una cosa se muestran como un pequeño mapa de cada zona en tu estilo de mapa, con un punto por cada lugar; un clic abre allí el mapa grande.",
  ["Zephras Isle no longer shows an empty map in the Blizzard, Modern, Pencil and Parchment styles."] = "Zephras Isle ya no muestra un mapa vacío en los estilos Blizzard, Modern, Pencil y Parchment.",
  ["The zones Forever added now have their people, objects, quest hand-ins, objectives and objective texts, and the airships to Zephras Isle are on the routes."] = "Las zonas que añadió Forever ahora tienen sus habitantes, objetos, entregas de misiones, objetivos y textos de objetivos, y los dirigibles a Zephras Isle están en las rutas.",
  ["A zone's tile shows the zone as a small map, and opening a part of a zone shows that part's people, monsters or quests as dots on the zone's map."] = "El mosaico de una zona muestra la zona como un pequeño mapa, y abrir una parte de una zona muestra los habitantes, monstruos o misiones de esa parte como puntos en el mapa de la zona.",
  ["Forever's vendors show their stock, quests show the XP players measured and the rewards seen in Forever, and more Classic creatures have a place on the map."] = "Los vendedores de Forever muestran su inventario, las misiones muestran la XP medida por los jugadores y las recompensas vistas en Forever, y más criaturas de Classic tienen un lugar en el mapa.",
  ['The search no longer hangs on "Searching ..." while the quest texts are not loaded.'] = "La búsqueda ya no se queda colgada en 'Buscando ...' mientras los textos de las misiones no están cargados.",
  ["The Browser's lists open on everything instead of jumping to your zone, and most have a Zone filter."] = "Las listas del Navegador se abren en todo, en lugar de saltar a tu zona, y la mayoría tienen un filtro de zona.",
  ["The Browser has Gold Stories and All Notes in its top row, farm spots link to their story in the book, and a setting chooses the style of the mini maps."] = "El Navegador tiene Historias de oro y Todas las notas en su fila superior, los lugares de farmeo enlazan con su historia en el libro, y un ajuste elige el estilo de los minimapas.",
  ["Routes now lead to the doors of the City of Dalaran, the Excavation Site in the Wetlands, the Ruins of Lordaeron and the Hall of Thanes."] = "Las rutas ahora llevan a las puertas de la ciudad de Dalaran, al Sitio de excavación de las Wetlands, a las Ruinas de Lordaeron y al Salón de los Thanes.",
  ["Every Forever market now shows its own auction prices where they exist, and says which market a price comes from."] = "Cada mercado de Forever ahora muestra sus propios precios de subasta donde existen, e indica de qué mercado procede un precio.",
  ["The Browser's search groups its results by list and every category button says how many it found; mini maps show where you stand; a search typed inside a zone stays in that zone; item and recipe tiles say what they are; chains show on the map, route and list their rewards."] = "La búsqueda del Navegador agrupa sus resultados por lista, y cada botón de categoría indica cuántos encontró; los minimapas muestran dónde estás; una búsqueda escrita dentro de una zona se queda en esa zona; los mosaicos de objetos y recetas dicen qué son; las cadenas aparecen en el mapa, en la ruta y en la lista con sus recompensas.",
  ["Stormwind on the Blizzard map style is the same city zoomed out and zoomed in, and the sea in the map styles no longer shows flat patches around the coasts."] = "Stormwind en el estilo de mapa Blizzard es la misma ciudad alejada y acercada, y el mar en los estilos de mapa ya no muestra manchas planas alrededor de las costas.",
  ["Auction prices left over from the beta are now labelled as such."] = "Los precios de subasta que quedaron de la beta ahora se marcan como tales.",
  ["Gold shows craft margins, disenchant value, whether a price is high or low in its range, a ledger of your sales and purchases, the market's best hours, and prices from AHledger, Auctionator or TSM when you have them."] = "Gold muestra los márgenes de fabricación, el valor de desencantamiento, si un precio es alto o bajo dentro de su rango, un libro de tus ventas y compras, las mejores horas del mercado y los precios de AHledger, Auctionator o TSM si los tienes.",
  ["Routes to Zephras Isle use Dalaran's skyboat, the skycutter at Skywatcher Plateau and, for the Alliance, the portal in Stormwind's Wizard's Sanctum."] = "Las rutas a Zephras Isle usan el bote celeste de Dalaran, el skycutter de Skywatcher Plateau y, para la Alianza, el portal del Sanctum del Mago de Stormwind.",
  ["The gold stories no longer judge what they tell: the stamps, the verified and refuted labels and the status filter on farm spots are gone."] = "Las historias de oro ya no juzgan lo que cuentan: los sellos, las etiquetas de verificado y refutado y el filtro de estado en los lugares de farmeo han desaparecido.",
  ["Bastian's Gold Adventures opens on a painted map of the world with every story as a picture with its level; a click opens the story, and the book stays one tab away."] = "Bastian's Gold Adventures se abre en un mapa del mundo pintado, con cada historia como una imagen con su nivel; un clic abre la historia, y el libro queda a una pestaña de distancia.",
  ["Every gold story is open from the start."] = "Cada historia de oro está abierta desde el principio.",
  ["The Rumour mill is now a plain list of what travellers are saying this week, one line each with who said it and the video, one click from the map."] = "La Fábrica de rumores es ahora una lista sencilla de lo que dicen los viajeros esta semana, una línea cada uno con quién lo dijo y el vídeo, a un clic del mapa.",
  ["The stories' window is now called Bastian's Gold Adventures, and it has a new story: Wolf Flanks in Duskwood."] = "La ventana de las historias ahora se llama Bastian's Gold Adventures y tiene una historia nueva: Wolf Flanks in Duskwood.",
  ["Quests: right-click a quest in your log to abandon it; the game asks first."] = "Misiones: clic derecho en una misión de tu registro para abandonarla; el juego pregunta antes.",
  ["Chat: the Up and Down keys recall your sent lines on Forever too (Alt+Up stays the game's)."] = "Chat: las flechas arriba y abajo recuperan tus líneas enviadas también en Forever (Alt+Arriba sigue siendo del juego).",
  ["Orbiter: hovering a quest mark shows the quest's chain position and its rewards (money, reputation, items)."] = "Orbiter: al pasar el ratón por una marca de misión se muestran su posición en la cadena y sus recompensas (dinero, reputación, objetos).",
  ["Quests: the zone view no longer errors on quests that are new in Forever."] = "Misiones: la vista de zona ya no da error con las misiones nuevas en Forever.",
  ["Core: no catalogue warning when a voice line starts or a quest reward loads."] = "Core: sin aviso de catálogo cuando empieza una línea de voz o se carga una recompensa de misión.",
  ["Bastian's minimap shows the herbs, ore and creatures your tracking finds on its own styles too, and the game's tracking button is back in its tools row."] = "El minimapa de Bastian muestra también, en sus propios estilos, las hierbas, minerales y criaturas que encuentra tu rastreo, y el botón de rastreo del juego vuelve a su barra de herramientas.",
  ["The session plan (what fits into the next 30 to 180 minutes) moved from Route's Explore to Bastian's Gold and is off until you switch it on in Gold's settings."] = "El plan de sesión (lo que cabe en los próximos 30 a 180 minutos) pasó de Explorar de Route a Bastian's Gold y queda apagado hasta que lo actives en los ajustes de Gold.",
  ["Other addons can ask Bastian's for any thing's name and places, your notes near a spot and your gold income through Bastians.API."] = "Otros addons pueden preguntar a Bastian's, a través de Bastians.API, el nombre y los lugares de cualquier cosa, tus notas cerca de un punto y tus ingresos de oro.",
  ["When Bastian's Helpers restocks an item, it tells you if another vendor sells it cheaper and where."] = "Cuando Bastian's Helpers repone un objeto, te dice si otro vendedor lo vende más barato y dónde.",
  ["What's new speaks your language: German, French, Spanish, Korean and Chinese."] = "Novedades habla tu idioma: alemán, francés, español, coreano y chino.",
  ["An item's price page shows a small chart of the prices your own auction house scans saw over the last two weeks."] = "La página de precio de un objeto muestra una pequeña gráfica de los precios que vieron tus propios escaneos de la casa de subastas en las últimas dos semanas.",
  ["Mail rules: tell Helpers which character gets your herbs, ore, cloth and more, and one click beside the send tab fills the mail."] = "Reglas de correo: dile a Helpers qué personaje recibe tus hierbas, menas, telas y más; un clic junto a la pestaña de envío rellena el correo.",
  ["Campfire can share your fire on a public channel and show everyone's fires (off by default, with a block list)."] = "Campfire puede compartir tu fogata en un canal público y mostrar las fogatas de todos (desactivado por defecto, con una lista de bloqueo).",
  ["Bastian's Suite now speaks Russian and Brazilian Portuguese."] = "Bastian's Suite ahora habla ruso y portugués de Brasil.",
  ["A Gestures command can now cast, use and target: /cast and friends run as a macro when you click the wedge."] = "Un comando de Gestures ahora puede lanzar, usar y fijar objetivo: /cast y compañía se ejecutan como macro al hacer clic en la cuña.",
  ["Other addons can now read and set Bastian's waypoint, read the account's gold and the suite's item sets through Bastians.API."] = "Otros addons ahora pueden leer y fijar el punto de ruta de Bastian's, leer el oro de la cuenta y los conjuntos de objetos de la suite a través de Bastians.API.",
  ["Spoken 3.8.0, the launch client's copy, is now the version the suite was tested with; the hub no longer flags it as newer."] = "Spoken 3.8.0, la versión del cliente de lanzamiento, cuenta ahora como probada; el centro ya no la marca como más nueva.",
  ["The game's voice that reads quest texts is a woman's by default and can be chosen in the Orbiter's settings."] = "La voz del juego que lee los textos de misión es por defecto una voz de mujer y se puede elegir en los ajustes del Orbiter.",
  ["Without Spoken, the Orbiter reads a quest's text with the game's own voice (Accessibility settings)."] = "Sin Spoken, el Orbiter lee el texto de una misión con la voz del juego (ajustes de accesibilidad).",
  ["Bastian's Orbiter (the Voice addon, renamed): the panel keeps its place and grows around its middle, says what it plays and what a click did, has pictogram controls and its own minimap button; the game's settings pages of the suite scroll."] = "Bastian's Orbiter (el addon Voice, renombrado): el panel conserva su sitio y crece alrededor de su centro, dice qué reproduce y qué hizo un clic, tiene controles con pictogramas y su propio botón de minimapa; las páginas de ajustes de la suite en el juego se desplazan.",
  ["Bastian's Voice: Play on quests, zones, areas, bosses and books where Spoken has a line, the Lore Orbit around you, and quest conversations without the game's windows (off by default)."] = "Bastian's Voice: reproducción en misiones, zonas, áreas, jefes y libros donde Spoken tiene una línea, la Órbita de historias a tu alrededor y conversaciones de misión sin las ventanas del juego (desactivado por defecto).",
  ["A note you add on a dungeon's page (or any other page) now shows on that page."] = "Una nota que añades en la página de una mazmorra (o de cualquier otra página) ahora se muestra en esa página.",
  ["The minimap's search finds only NPCs, quests, zones, your notes and bookmarks, and marks the place it jumps to; a quest marks its quest giver."] = "La búsqueda del minimapa solo encuentra PNJ, misiones, zonas, tus notas y marcadores, y marca el lugar al que salta; una misión marca a quien la da.",
  ['"Show on map" now draws what you chose (its icon and name at every place) and selects it, even when its layer is off.'] = '"Mostrar en el mapa" ahora dibuja lo que elegiste (su icono y su nombre en cada lugar) y lo selecciona, aunque su capa esté desactivada.',
  ["The map has a Dungeons and raids layer, and it switches on by itself when you pick a dungeon in the Browser."] = 'El mapa tiene una capa "Calabozos y bandas" que se activa sola cuando eliges una mazmorra en el Browser.',
  ["New app Bastian's Helpers: sells junk, repairs, restocks, takes all mail, helps at quest givers and shows IDs on tooltips."] = "Nueva aplicación Bastian's Helpers: vende chatarra, repara, repone existencias, recoge todo el correo, ayuda con quienes dan misiones y muestra los ID en las descripciones emergentes.",
  ["The dungeon pages name the right bosses; some showed an unrelated creature (Shadowfang Keep's first boss as Archaedas) with loot that was not its own."] = "Las páginas de mazmorra nombran a los jefes correctos; algunas mostraban una criatura sin relación (el primer jefe del Castillo de Colmillo Oscuro como Archaedas) con botín que no era suyo.",
  ["Minimap buttons close what they opened; Gestures' button opens its options; a switched-off app's button leads to its switch; a new button shows the welcome again."] = "Los botones del minimapa cierran lo que abrieron; el botón de Gestos abre sus opciones; el botón de una aplicación desactivada lleva a su interruptor; un botón nuevo vuelve a mostrar la bienvenida.",
  ["Forever's own dungeons (Dalaran, the Wetlands excavation, the Hall of Thanes, the Ruins of Lordaeron) now show Santiago Reyes' hand-drawn maps with the bosses marked - thank you, Santiago!"] = "Las mazmorras propias de Forever (Dalaran, la excavación de los Humedales, el Salón de los Thanes, las Ruinas de Lordaeron) ahora muestran los mapas dibujados a mano por Santiago Reyes con los jefes marcados - ¡gracias, Santiago!",
  ["German, French and Spanish players read most quests' whole texts in their language, and the AddOn list speaks every language of the suite."] = "Los jugadores alemanes, franceses y españoles leen los textos completos de la mayoría de las misiones en su idioma, y la lista de AddOns habla todos los idiomas de la suite.",
  ["The game's AddOn list shows the suite as one folding \"Bastian's Suite\" header with the data packs and map styles folded under their app, in Korean and Chinese too."] = 'La lista de AddOns del juego muestra la suite como un único encabezado plegable "Bastian\'s Suite", con los paquetes de datos y los estilos de mapa plegados bajo su aplicación, también en coreano y chino.',
  ["Korean and Chinese players read the quests' whole texts in their language, and Bastian's Chat speaks French, Spanish, Korean and Chinese."] = "Los jugadores coreanos y chinos leen los textos completos de las misiones en su idioma, y Bastian's Chat habla francés, español, coreano y chino.",
  ["With Total RP 3 or MyRolePlay, Chat, Gestures and the Orbiter show other players' roleplay names."] = "Con Total RP 3 o MyRolePlay, Chat, Gestures y el Orbiter muestran los nombres de rol de otros jugadores.",
  ["A new welcome: choose the Wanderer or the Scholar with a picture of your own race, set up your pack, and try your first five minutes step by step."] = "Una nueva bienvenida: elige al Caminante o al Erudito con una imagen de tu propia raza, configura tu paquete y prueba tus primeros cinco minutos paso a paso.",
  ["Bastian's Campfire: a card while a fire is near, a camp ring in Gestures, share the fire with your group and guild, and a planner of every camp feature."] = "Bastian's Campfire: una tarjeta cuando hay una hoguera cerca, un anillo de campamento en Gestos, compartir la hoguera con tu grupo y tu hermandad, y un planificador de todas las funciones del campamento.",
  ["Emotes in Bastian's Chat now show in the colour scheme's own emote colour, for roleplay."] = "Los emotes en Bastian's Chat se muestran ahora con el color de emote propio de la combinación de colores, para el rol.",
  ["A Gestures wedge can run one of your own macros with a click, and runs the game's own commands such as /reload; Quests' item buttons work with \"cast on key down\"."] = 'Un sector de Gestos puede ejecutar una de tus macros con un clic y ejecuta los comandos del juego como /reload; los botones de objeto de Quests funcionan con "lanzar al pulsar la tecla".',
  ["The Korean and Chinese texts of the suite read naturally and use the game's own terms."] = "Los textos en coreano y chino de la suite se leen con naturalidad y usan los términos propios del juego.",
  ["Build your Gestures rings as you like: name them, pick any emote, your own lines, commands, the suite's and the game's controls through one filter; the wheel turns the right way; a conversation's choices no longer overlap on the Orbiter."] = "Crea tus anillos de Gestos a tu gusto: ponles nombre, elige cualquier emote, tus propias líneas, comandos y los controles de la suite y del juego mediante un único filtro; la rueda gira en el sentido correcto; las opciones de una conversación ya no se solapan en el Orbiter.",
  ["When someone challenges, trades or invites you, Gestures offers a bow, a wave or a polite decline; Chat's + menu has a Roleplay tab."] = "Cuando alguien te desafía, comercia contigo o te invita, Gestos ofrece una reverencia, un saludo o una negativa educada; el menú + del Chat tiene una pestaña de Rol.",
  ["Gestures' Route home, Mark heard and Toggle the tracker wedges light up."] = 'Los sectores "Ruta a casa", "Marcar como escuchado" y "Mostrar u ocultar el rastreador" de Gestos ahora se iluminan.',
  ["The Orbiter says when your Spoken is newer or older than the suite was tested with, never talks over Spoken or Spoken Players, and Bastian's Helpers, Chat and the Orbiter show up on broker displays; other addons can ask who knows a recipe, let the Orbiter speak, read your play preset and open any app."] = "El Orbiter avisa cuando tu Spoken es más nuevo o más antiguo que la versión con la que se probó la suite, nunca habla por encima de Spoken o Spoken Players, y Bastian's Helpers, Chat y el Orbiter aparecen en las pantallas de broker; otros addons pueden preguntar quién conoce una receta, hacer hablar al Orbiter, leer tu perfil de juego y abrir cualquier aplicación.",
  ["Every app wears its own mark on the minimap, in the hub, on broker displays and in the AddOns list: a compass star for the suite, a scroll for Quests, a pin for the Map, a lens for the Browser, a balance for Gold, a signpost for Route, a quill for Notes, two characters for Alts, a wrench for Helpers, bubbles for Chat, a hand for Gestures."] = "Cada aplicación lleva su propia marca en el minimapa, en el hub, en las pantallas de broker y en la lista de AddOns: una estrella de brújula para la suite, un pergamino para Quests, una marca para el mapa, una lupa para el Browser, una balanza para Gold, un poste indicador para Route, una pluma para Notes, dos personajes para Alts, una llave inglesa para Helpers, burbujas para Chat, una mano para Gestures.",
  ["Choose how you play at the first start: the Wanderer hears Azeroth with nearly no UI, the Scholar has every quest, creature, item and place one click away; Bastian's Gestures brings emote rings and courtesy; the hub explains every app and key."] = "Elige al empezar cómo juegas: el Caminante oye Azeroth casi sin interfaz, el Erudito tiene cada misión, criatura, objeto y lugar a un clic; Bastian's Gestures trae anillos de emotes y cortesía; el hub explica cada aplicación y cada tecla.",
  ["Every button shows its pictogram again and the words sit where they belong; chat tabs and buttons are easy to tell apart; the Orbiter's controls click with a creature shown, its hub drags it, and its answers are symbols; an item's page says which of your characters has it."] = "Cada botón vuelve a mostrar su pictograma y las palabras están donde deben; las pestañas de chat y los botones se distinguen con facilidad; los controles del Orbiter responden al clic cuando se muestra una criatura, su hub lo arrastra y sus respuestas son símbolos; la página de un objeto indica cuál de tus personajes lo tiene.",
  ["Trainers say what they train on the map and on their page, and their list of spells shows who of your characters knows each one; item lists filter by who owns an item; the Orbiter hides with the clear-screen key and drags by its hub; the Browser's hover preview is a setting."] = "Los instructores indican en el mapa y en su página qué enseñan, y su lista de hechizos muestra cuál de tus personajes conoce cada uno; las listas de objetos se filtran por quién posee un objeto; el Orbiter se oculta con la tecla de despejar la pantalla y se arrastra por su hub; la vista previa al pasar el ratón del Browser es un ajuste.",
  ["Every app offers a data-broker feed (Titan, Bazooka, ElvUI and the like), the Addon Compartment lists the suite, bag addons get the suite's item sets, and other addons can read the suite through Bastians.API."] = "Cada aplicación ofrece una fuente de data broker (Titan, Bazooka, ElvUI y similares), el compartimento de addons muestra la suite, los addons de bolsas reciben los conjuntos de objetos de la suite y otros addons pueden leer la suite mediante Bastians.API.",
  ["The Orbiter's bubbles glide to their places and the one that plays is coloured; Show on map always draws what you chose; the junk filter also cleans the lines already on screen; the game's voice is found once the client lists it."] = 'Las burbujas del Orbiter se deslizan a su sitio y la que suena aparece coloreada; "Mostrar en el mapa" siempre dibuja lo que elegiste; el filtro de chatarra también limpia las líneas que ya están en pantalla; la voz del juego se encuentra en cuanto el cliente la lista.',
  ["Seven looks to pick from, including Night, Glass and Parchment; every button of the suite shows a pictogram; every colour scheme is checked for readable text."] = "Siete aspectos entre los que elegir, entre ellos Noche, Cristal y Pergamino; cada botón de la suite muestra un pictograma; cada combinación de colores se ha comprobado para que el texto sea legible.",
  ["the Browser's filter pills use the pane's width and the first row is never hidden, the Mobs search works again, zones appear once, a preview needs Shift, and a note saved on a page shows at once."] = "Las etiquetas de filtro del Browser usan el ancho del panel y la primera fila nunca queda oculta, la búsqueda de monstruos vuelve a funcionar, las zonas aparecen una sola vez, una vista previa requiere Shift y una nota guardada en una página se muestra al instante.",
  ['one search syntax in every box (words, "phrases", OR, -not, field:value, level>30), the text keys Ctrl+Backspace/Delete/Left/Right, a key that clears the screen for role play, a lock on every window, and the new look engine behind Modern and WoW.'] = 'Una única sintaxis de búsqueda en cada cuadro (palabras, "frases", OR, -not, field:value, level>30), las teclas de texto Ctrl+Backspace/Delete/Left/Right, una tecla que despeja la pantalla para el rol, un candado en cada ventana y el nuevo motor de aspecto detrás de Moderno y WoW.',
  ['Bastian\'s Helpers also writes its notices into a chat tab named "Addons" when you have one.'] = 'Bastian\'s Helpers también escribe sus avisos en una pestaña de chat llamada "Addons" si tienes una.',
  ['The colour picker opens in front of the settings, and no "blocked" message appears in combat.'] = 'El selector de color se abre delante de los ajustes y ya no aparece ningún mensaje de "bloqueado" en combate.',
  ["The map's layer bar names each icon the moment you point at it."] = "La barra de capas del mapa nombra cada icono en cuanto lo señalas.",
  ["Other addons can ask Bastian's for prices, quest state, the active route and travel times, start a route, and listen to its events through Bastians.API."] = "Otros addons pueden pedirle a Bastian's precios, el estado de las misiones, la ruta activa y los tiempos de viaje, iniciar una ruta y escuchar sus eventos mediante Bastians.API.",
  ["Wide buttons in the WoW look keep the game's rounded ends instead of stretching them."] = "Los botones anchos con el aspecto de WoW conservan los extremos redondeados del juego en lugar de estirarlos.",
  ["Bastian's apps show in Titan Panel, Bazooka, EllesmereUI's data bars and every other LibDataBroker display, in the addon compartment, and sort your bags in BetterBags, Baganator and AdiBags."] = "Las aplicaciones de Bastian's aparecen en Titan Panel, Bazooka, las barras de datos de EllesmereUI y cualquier otra pantalla de LibDataBroker, en el compartimento de addons, y ordenan tus bolsas en BetterBags, Baganator y AdiBags.",
  ["Bastian's Chat gets a live tab filter, tab windows that dock back, a Messenger of the WhatsApp kind with class icons and a search, and a lock on every chat window."] = "Bastian's Chat recibe un filtro de pestañas en vivo, ventanas de pestaña que vuelven a acoplarse, un Messenger al estilo de WhatsApp con iconos de clase y una búsqueda, y un candado en cada ventana de chat.",
  ["All %d"] = "Los %d",
  ["Step inside"] = "Entrar",
  -- UI/Dossier.lua: tabs inside a sheet, facts as tiles (ADR 0058, 07.11.2026)
  ["Overview"] = "Resumen",
  ["unknown"] = "desconocido",
}
